using MechanicalDesigns.Domain.Enums;using MechanicalDesigns.Infrastructure.Persistence;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace MechanicalDesigns.Api.Controllers;
[ApiController][Authorize(Policy="AdminOnly")][Route("api/admin/dashboard")]public sealed class AdminDashboardController(ApplicationDbContext db):ControllerBase{
 [HttpGet("overview")]public async Task<IActionResult>Overview(CancellationToken ct)=>Ok(new{totalOrders=await db.Orders.CountAsync(ct),pendingOrders=await db.Orders.CountAsync(x=>x.OrderStatus==OrderStatus.PendingConfirmation,ct),confirmedOrders=await db.Orders.CountAsync(x=>x.OrderStatus==OrderStatus.Confirmed,ct),deliveredOrders=await db.Orders.CountAsync(x=>x.OrderStatus==OrderStatus.Delivered,ct),cancelledOrders=await db.Orders.CountAsync(x=>x.OrderStatus==OrderStatus.Cancelled,ct),totalCustomers=await db.Users.CountAsync(x=>x.Role==UserRole.Client,ct),totalProducts=await db.Products.CountAsync(ct),outOfStockProducts=await db.Products.CountAsync(x=>x.StockQuantity==0,ct),totalRevenue=await db.Orders.Where(x=>x.OrderStatus==OrderStatus.Delivered&&x.PaymentStatus==PaymentStatus.Paid).SumAsync(x=>(decimal?)x.Total,ct)??0,customOrdersCount=await db.CustomOrders.CountAsync(ct),reviewsCount=await db.Reviews.CountAsync(ct),averageRating=await db.Reviews.Where(x=>x.Status==ReviewStatus.Approved).AverageAsync(x=>(decimal?)x.Rating,ct)??0});
 [HttpGet("recent-orders")]public async Task<IActionResult>Recent(CancellationToken ct)=>Ok(await db.Orders.AsNoTracking().OrderByDescending(x=>x.CreatedAt).Take(10).Select(x=>new{x.Id,x.OrderNumber,x.CustomerName,x.Total,x.OrderStatus,x.CreatedAt}).ToListAsync(ct));
 [HttpGet("best-selling-products")]public async Task<IActionResult>Best(CancellationToken ct)=>Ok(await db.OrderItems.AsNoTracking().Where(x=>x.Order.OrderStatus==OrderStatus.Delivered).GroupBy(x=>new{x.ProductId,x.ProductTitleAr,x.ProductTitleEn}).Select(g=>new{g.Key.ProductId,g.Key.ProductTitleAr,g.Key.ProductTitleEn,quantitySold=g.Sum(x=>x.Quantity),revenue=g.Sum(x=>x.TotalPrice)}).OrderByDescending(x=>x.quantitySold).Take(10).ToListAsync(ct));}
